drop function if exists public.create_presale_order(uuid,numeric,text);
drop function if exists public.submit_payment(uuid,uuid,numeric,text,text,text);
drop function if exists public.confirm_payment_and_allocate(uuid,text);

-- Privileged RPCs are callable only by the service role. Edge Functions authenticate the user JWT first and pass the verified actor ID.
create or replace function public.create_presale_order(p_actor_id uuid,p_round_id uuid,p_purchase_value numeric,p_purchase_currency text) returns public.presale_orders language plpgsql security definer set search_path=public as $$ declare r public.presale_rounds%rowtype; o public.presale_orders%rowtype; ref text:='DTR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)); begin if p_actor_id is null or not exists(select 1 from auth.users where id=p_actor_id) then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if; select * into r from public.presale_rounds where id=p_round_id for share; if not found or r.status <> 'ACTIVE' then raise exception 'ROUND_NOT_ACTIVE' using errcode='P0001'; end if; if r.price_numeric is null or r.price_numeric <= 0 then raise exception 'PRICE_NOT_CONFIGURED' using errcode='P0001'; end if; insert into public.presale_orders(order_reference,investor_id,round_id,purchase_value,purchase_currency,locked_price_numeric,locked_price_currency,expected_dtr,expires_at,status) values(ref,p_actor_id,r.id,p_purchase_value,p_purchase_currency,r.price_numeric,coalesce(r.price_currency,p_purchase_currency),floor(p_purchase_value/r.price_numeric),coalesce(r.ends_at,now()+interval '24 hours'),'AWAITING_PAYMENT') returning * into o; return o; end; $$;
revoke all on function public.create_presale_order(uuid,uuid,numeric,text) from public,anon,authenticated; grant execute on function public.create_presale_order(uuid,uuid,numeric,text) to service_role;

create or replace function public.submit_payment(p_actor_id uuid,p_order_id uuid,p_payment_route_id uuid,p_amount numeric,p_asset_code text,p_network_code text,p_transaction_hash text) returns public.payment_submissions language plpgsql security definer set search_path=public as $$ declare o public.presale_orders%rowtype; r public.payment_routes%rowtype; p public.payment_submissions%rowtype; begin if p_actor_id is null or not exists(select 1 from auth.users where id=p_actor_id) then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if; select * into o from public.presale_orders where id=p_order_id and investor_id=p_actor_id for update; if not found then raise exception 'ORDER_NOT_FOUND' using errcode='P0002'; end if; if o.status <> 'AWAITING_PAYMENT' then raise exception 'INVALID_ORDER_STATE' using errcode='P0001'; end if; if o.expires_at is not null and o.expires_at < now() then update public.presale_orders set status='EXPIRED',updated_at=now() where id=o.id; raise exception 'ORDER_EXPIRED' using errcode='P0001'; end if; select * into r from public.payment_routes where id=p_payment_route_id and round_id=o.round_id and active=true; if not found or r.asset_code <> p_asset_code or r.network_code <> p_network_code then raise exception 'ROUTE_MISMATCH' using errcode='P0001'; end if; insert into public.payment_submissions(order_id,payment_route_id,amount,asset_code,network_code,transaction_hash,status) values(o.id,r.id,p_amount,p_asset_code,p_network_code,p_transaction_hash,'SUBMITTED') returning * into p; update public.presale_orders set status='PAYMENT_SUBMITTED',updated_at=now() where id=o.id; return p; exception when unique_violation then raise exception 'TRANSACTION_REFERENCE_ALREADY_SUBMITTED' using errcode='23505'; end; $$;
revoke all on function public.submit_payment(uuid,uuid,uuid,numeric,text,text,text) from public,anon,authenticated; grant execute on function public.submit_payment(uuid,uuid,uuid,numeric,text,text,text) to service_role;

create or replace function public.confirm_payment_and_allocate(p_actor_id uuid,p_payment_submission_id uuid,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_order public.presale_orders%rowtype; v_payment public.payment_submissions%rowtype; v_allocation public.dtr_allocations%rowtype; v_ref text:='ALLOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20)); begin if p_actor_id is null or not exists(select 1 from public.admin_roles where user_id=p_actor_id and role in('ADMIN','SUPER_ADMIN','REVIEWER')) then raise exception 'ADMIN_AUTHORIZATION_REQUIRED' using errcode='42501'; end if; select * into v_payment from public.payment_submissions where id=p_payment_submission_id for update; if not found then raise exception 'PAYMENT_NOT_FOUND' using errcode='P0002'; end if; select * into v_order from public.presale_orders where id=v_payment.order_id for update; if not found then raise exception 'ORDER_NOT_FOUND' using errcode='P0002'; end if; if v_order.status in('CONFIRMED','DTR_ALLOCATED') or exists(select 1 from public.dtr_allocations where order_id=v_order.id) then raise exception 'ORDER_ALREADY_ALLOCATED' using errcode='23505'; end if; if v_order.status not in('UNDER_REVIEW','PAYMENT_SUBMITTED') then raise exception 'INVALID_ORDER_STATE' using errcode='P0001'; end if; update public.payment_submissions set status='VERIFIED',updated_at=now() where id=v_payment.id; insert into public.payment_verifications(payment_submission_id,order_id,reviewer_id,status,reason) values(v_payment.id,v_order.id,p_actor_id,'CONFIRMED',p_reason); insert into public.dtr_allocations(order_id,investor_id,payment_submission_id,dtr_amount,allocation_reason,created_by) values(v_order.id,v_order.investor_id,v_payment.id,v_order.expected_dtr,coalesce(p_reason,'Verified payment'),p_actor_id) returning * into v_allocation; insert into public.allocation_ledger(allocation_id,investor_id,order_id,payment_submission_id,dtr_amount,reason,administrator_id,audit_reference) values(v_allocation.id,v_order.investor_id,v_order.id,v_payment.id,v_order.expected_dtr,coalesce(p_reason,'Verified payment'),p_actor_id,v_ref); insert into public.admin_actions(administrator_id,order_id,payment_submission_id,action,reason) values(p_actor_id,v_order.id,v_payment.id,'CONFIRM',p_reason); insert into public.audit_events(actor_id,event_type,order_id,payment_submission_id,allocation_id,audit_reference,metadata) values(p_actor_id,'PAYMENT_CONFIRMED_AND_ALLOCATED',v_order.id,v_payment.id,v_allocation.id,v_ref,jsonb_build_object('dtr_amount',v_order.expected_dtr,'idempotency_key',v_payment.id)); update public.presale_orders set status='DTR_ALLOCATED',updated_at=now() where id=v_order.id; return jsonb_build_object('order_id',v_order.id,'payment_submission_id',v_payment.id,'allocation_id',v_allocation.id,'dtr_amount',v_order.expected_dtr,'audit_reference',v_ref); exception when unique_violation then raise exception 'ALLOCATION_ALREADY_EXISTS' using errcode='23505'; end; $$;
revoke all on function public.confirm_payment_and_allocate(uuid,uuid,text) from public,anon,authenticated; grant execute on function public.confirm_payment_and_allocate(uuid,uuid,text) to service_role;
